  var s = m.series||[];
  out += '<div class="grid three" style="margin-top:12px">';
  out += '<div class="card"><h2>Charges over time</h2>' +
    lineChart(s.map(function(p){return p.label;}),
      [{name:'Current', color:C.blue, values:s.map(function(p){return p.charges;})},
       {name:'Prior year', color:C.teal, dash:true, values:s.map(function(p){return p.priorCharges;})}], 175) +
    legend([{name:'Current',color:C.blue},{name:'Prior year',color:C.teal}]) + '</div>';

  var bd = m.breakdown||[];
  var totalCharges = bd.reduce(function(a,b){return a+b.charges;},0);
  out += '<div class="card"><h2>Cost breakdown</h2>' + donut(bd, money(totalCharges)) +
    legend(bd.map(function(b){ return {name: b.name+' '+pct(b.pct,0)}; })) + '</div>';

  out += '<div class="card tree"><h2>Utility hierarchy</h2>' + treeHtml(m.tree, totalCharges) + '</div>';
  out += '</div>';
  return out;
