  var mx = Math.max.apply(null, markers.map(function(p){return p[key];})) || 1;

  return '<div class="mapwrap">' + markers.map(function(p){
    var x = 6 + (p.long-lo0)/(lo1-lo0)*88;
    var y = 92 - (p.lat-la0)/(la1-la0)*84;          // north at the top
    var d = 10 + Math.sqrt(Math.max(0,p[key])/mx)*24;
    var val = key === 'consumption' ? num(p.consumption) : money(p.charges);
    return '<i class="pin" style="left:'+x.toFixed(1)+'%;top:'+y.toFixed(1)+'%;width:'+d.toFixed(0)+
           'px;height:'+d.toFixed(0)+'px" title="'+esc(p.title+' — '+val)+'"></i>';
  }).join('') + '</div>';
}

function treeHtml(tree, total){
  if(!tree || !tree.length) return '<div class="empty">Utility tree query has not run</div>';
  var out = '<div><span>Portfolio total</span><strong>'+money(total)+'</strong></div>';
  tree.forEach(function(u){
    out += '<div><span>'+esc(u.name)+'</span><strong>'+money(u.charges)+'</strong></div>';
    (u.children||[]).slice(0,4).forEach(function(v){
      out += '<div class="l1"><span>'+esc(v.name)+'</span><strong>'+money(v.charges)+'</strong></div>';
    });
  });
  return out;
}

